Sign In:
query SignIn($auth: SignInInput!) {
  signIn(auth: $auth) {
    _id
    firstName
    lastName
    emailId
    token
    defaultAccount
    organisationId
  }
}

Org List:
query OrgList {
  accounts {
    organisationId
    name
    isActive
    isAccepted
    isAdmin
  }
}

Project List:
query ProjectList($params: ParamInput!) {
  projectOverview(params: $params) {
    _id
    name
    description
    active
    organisationId
    location { placeName lat lng }
    userCount { _id userCount }
    deviceCount { _id deviceCount }
    clusterCount { _id clusterCount }
    nonLoRaWANDeviceCount { _id nonLoRaWANDeviceCount }
  }
}

Device List:
query DeviceList($params: ParamInput!) {
  projects(params: $params) {
    _id
    name
    clusters {
      _id
      name
      devices {
        _id
        name
        devEui
        hardwareId
        timestamp
      }
    }
  }
}

Device Details:
query DeviceDetails($params: ParamInput!) {
  projects(params: $params) {
    _id
    name
    clusters {
      _id
      name
      devices {
        _id
        name
        description
        devEui
        organisationId
        projectId
        clusterId
        hardwareId
        networkId
        hardwareType
        timestamp
        deleted
        position { placeName lat lng }
        outputs { outputId outputName value label color }
        attributes { attributeId attributeName value }
      }
    }
  }
}

Module List:
query ModuleList($params: ParamInput!) {
  modules(params: $params) {
    _id
    label
    moduleType
    organisationId
  }
}

Send Downlink:
query SendDownlink($action: SendDownlinkInput!) {
  sendDownlink(action: $action) {
    timestamp
    type
    message
  }
}
